    color?: string;
}> = ({ name, className = '', width = 100, color = 'currentColor' }) => {
    const h = Math.round(width * 0.72);
    const filterId = `emboss-${name.split('').filter(c => (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')).join('')}`;
    return (
        <svg
            width={width}
            height={h}
            viewBox="0 0 80 56"
            fill="none"
            className={className}
