function formatMs(ms: number): string {
    const totalSec = ms / 1000;
    const mins = Math.floor(totalSec / 60);
    const secs = Math.floor(totalSec % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
}

import React, { useRef, useCallback, memo, useEffect } from 'react';
import { MoshRegion } from '../types';
import { Icon } from './Icon';

interface TimelineProps {
    duration: number; // seconds
    regions: MoshRegion[];
    selectedId: string | null;
    currentTime: number; // seconds
    isPlaying: boolean;
    isMuted: boolean;
    onPlayPause: () => void;
    onToggleMute: () => void;
    onSeek: (time: number) => void;
    onUpdateRegion: (id: string, changes: Partial<MoshRegion>) => void;
    onSelectRegion: (id: string) => void;
}

const MIN_BLOCK_MS = 200;

const MODE_COLORS: Record<string, string> = {
    liquid: '#009ebd',
    bloom: '#cc8e00',
    stutter: '#cc0088',
    reverse: '#00b362',
    pulse: '#d64300',
    transition: '#8000cc',
};

const MODE_LABELS: Record<string, string> = {
    liquid: 'Liquid',
    trail: 'Trail',
    bloom: 'Bloom',
    stutter: 'Stutter',
    reverse: 'Reverse',
    pulse: 'Pulse',
    shatter: 'Shatter',
    transition: 'Transition',
};

interface DragState {
    mode: 'move' | 'resize-start' | 'resize-end';
    activeId: string;
    startX: number;
    startDelay: number;
    startDuration: number;
    currentDelay: number;
    currentDuration: number;
}

export const Timeline: React.FC<TimelineProps> = memo(({
    duration, regions, selectedId, currentTime, isPlaying, isMuted,
    onPlayPause, onToggleMute, onSeek, onUpdateRegion, onSelectRegion,
}) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const blockRefs = useRef<Map<string, HTMLDivElement>>(new Map());
    const dragRef = useRef<DragState | null>(null);
    const playheadRef = useRef<HTMLDivElement>(null);

    const durationRef = useRef(duration);
    durationRef.current = duration;
    const onSeekRef = useRef(onSeek);
    onSeekRef.current = onSeek;
    const onSelectRegionRef = useRef(onSelectRegion);
    onSelectRegionRef.current = onSelectRegion;
    const onUpdateRegionRef = useRef(onUpdateRegion);
    onUpdateRegionRef.current = onUpdateRegion;

    // Update playhead position
    useEffect(() => {
        if (playheadRef.current && duration > 0) {
            playheadRef.current.style.left = `${(currentTime / duration) * 100}%`;
        }
    }, [currentTime, duration]);

    const getTimeFromX = useCallback((clientX: number) => {
        if (!containerRef.current || durationRef.current === 0) return 0;
        const rect = containerRef.current.getBoundingClientRect();
        const padding = 4;
        const width = rect.width - padding * 2;
        const x = clientX - rect.left - padding;
        return Math.max(0, Math.min(1, x / width)) * durationRef.current;
    }, []);

    /* ─── Seek (scrub playhead on track background) ─── */
    const handleTrackMouseDown = useCallback((e: React.MouseEvent) => {
        if ((e.target as HTMLElement).closest('[data-block-id]')) return;
        onSeekRef.current(getTimeFromX(e.clientX));
        const onMove = (ev: MouseEvent) => onSeekRef.current(getTimeFromX(ev.clientX));
        const onUp = () => {
            window.removeEventListener('mousemove', onMove);
            window.removeEventListener('mouseup', onUp);
        };
        window.addEventListener('mousemove', onMove);
        window.addEventListener('mouseup', onUp);
    }, [getTimeFromX]);

    /* ─── Block drag ─── */
    const startDrag = useCallback((e: React.MouseEvent, id: string, mode: 'move' | 'resize-start' | 'resize-end') => {
        e.stopPropagation();
        e.preventDefault();
        onSelectRegionRef.current(id);

        const region = regions.find(r => r.id === id);
        if (!region || !containerRef.current) return;

        dragRef.current = {
            mode,
            activeId: id,
            startX: e.clientX,
            startDelay: region.startMs,
            startDuration: region.durationMs,
            currentDelay: region.startMs,
            currentDuration: region.durationMs,
        };

        const draggedEl = blockRefs.current.get(id);
        if (draggedEl) {
            draggedEl.style.transition = 'none';
            draggedEl.style.zIndex = '25';
            draggedEl.style.opacity = '0.85';
        }

        document.body.style.cursor = mode === 'move' ? 'grabbing' : 'ew-resize';

        const onMove = (ev: MouseEvent) => {
            const drag = dragRef.current;
            if (!drag || !containerRef.current) return;

            const rect = containerRef.current.getBoundingClientRect();
            const deltaX = ev.clientX - drag.startX;
            const deltaTimeMs = (deltaX / rect.width) * durationRef.current * 1000;
            const totalMs = durationRef.current * 1000;

            let newDelay = drag.startDelay;
            let newDuration = drag.startDuration;

            if (drag.mode === 'move') {
                newDelay = Math.max(0, Math.min(totalMs - drag.startDuration, drag.startDelay + deltaTimeMs));
                newDuration = drag.startDuration;
            } else if (drag.mode === 'resize-start') {
                const rawDelay = drag.startDelay + deltaTimeMs;
                const maxDelay = (drag.startDelay + drag.startDuration) - MIN_BLOCK_MS;
                newDelay = Math.max(0, Math.min(maxDelay, rawDelay));
                newDuration = (drag.startDelay + drag.startDuration) - newDelay;
            } else {
                const rawEnd = (drag.startDelay + drag.startDuration) + deltaTimeMs;
                newDuration = Math.max(MIN_BLOCK_MS, Math.min(totalMs - drag.startDelay, rawEnd - drag.startDelay));
                newDelay = drag.startDelay;
            }

            const el = blockRefs.current.get(drag.activeId);
            if (el) {
                el.style.left = `${(newDelay / 1000 / durationRef.current) * 100}%`;
                el.style.width = `${(newDuration / 1000 / durationRef.current) * 100}%`;
            }

            drag.currentDelay = newDelay;
            drag.currentDuration = newDuration;
        };

        const onUp = () => {
            const drag = dragRef.current;
            if (drag) {
                const el = blockRefs.current.get(drag.activeId);
                if (el) {
                    el.style.transition = 'left 150ms ease-out, width 150ms ease-out, opacity 150ms ease-out';
                    el.style.opacity = '';
                    el.style.zIndex = '';
                }

                setTimeout(() => {
                    const el2 = blockRefs.current.get(drag.activeId);
                    if (el2) el2.style.transition = '';
                    onUpdateRegionRef.current(drag.activeId, {
                        startMs: Math.round(drag.currentDelay),
                        durationMs: Math.round(drag.currentDuration),
                    });
                }, 160);
            }

            document.body.style.cursor = '';
            dragRef.current = null;
            window.removeEventListener('mousemove', onMove);
            window.removeEventListener('mouseup', onUp);
        };

        window.addEventListener('mousemove', onMove);
        window.addEventListener('mouseup', onUp);
    }, [regions]);

    const setBlockRef = useCallback((id: string) => (el: HTMLDivElement | null) => {
        if (el) blockRefs.current.set(id, el);
        else blockRefs.current.delete(id);
    }, []);

    if (duration === 0) return null;

    return (
        <div className="w-full space-y-1 select-none flex flex-col">
            {/* Controls */}
            <div className="flex items-center justify-between px-0.5">
                <div className="flex items-center gap-2">
                    <div className="flex items-center gap-0.5">
                        <button onClick={onPlayPause}
                            className="w-[26px] h-[26px] flex items-center justify-center rounded-lg hover:bg-white/8 active:bg-white/12 transition-colors text-white/90">
                            <Icon name={isPlaying ? 'pause' : 'play_arrow'} size={15} filled />
                        </button>
                        <button onClick={onToggleMute}
                            className="w-[26px] h-[26px] flex items-center justify-center rounded-lg hover:bg-white/8 active:bg-white/12 transition-colors text-white/40 hover:text-white/70">
                            <Icon name={isMuted ? 'volume_off' : 'volume_up'} size={15} filled />
                        </button>
                    </div>
                    <span className="text-[10px] font-medium tracking-[0.3px] text-white/50 tabular-nums">
                        {formatTime(currentTime)}
                    </span>
                </div>
                <span className="text-[10px] font-medium tracking-[0.3px] text-white/50 tabular-nums">
                    {formatTime(duration)}
                </span>
            </div>

            <div
                ref={containerRef}
                onMouseDown={handleTrackMouseDown}
                className="relative h-[32px] w-full bg-[#1a1a1a]/60 rounded-lg cursor-pointer border border-white/[0.08] p-0.5"
            >
                <div className="absolute inset-x-0.5 inset-y-0">
                    {regions.map((region) => {
                        const startPercent = ((region.startMs || 0) / 1000 / duration) * 100;
                        const widthPercent = ((region.durationMs || 0) / 1000 / duration) * 100;
                        const isSelected = selectedId === region.id;
                        const color = MODE_COLORS[region.mode] || '#969696';

                        return (
                            <div
                                key={region.id}
                                ref={setBlockRef(region.id)}
                                data-block-id={region.id}
                                onMouseDown={(e) => startDrag(e, region.id, 'move')}
                                className={`absolute top-0.5 bottom-0.5 rounded-md z-10 cursor-grab active:cursor-grabbing border overflow-hidden group/clip will-change-[left,width] transition-colors shadow-[inset_1px_1px_2px_rgba(255,255,255,0.2),inset_-1px_-1px_3px_rgba(0,0,0,0.4)]\n                                    ${isSelected
                                        ? 'z-20'
                                        : 'hover:brightness-110'
                                    }`}
                                style={{
                                    left: `${startPercent}%`,
                                    width: `${widthPercent}%`,
                                    backgroundColor: isSelected ? color : `${color}88`,
                                    borderColor: isSelected ? color : `${color}44`,
                                }}
                            >
                                {/* Resize handles */}
                                <div onMouseDown={(e) => startDrag(e, region.id, 'resize-start')}
                                    className="absolute left-0 top-0 bottom-0 w-2 cursor-ew-resize hover:bg-white/20 z-30 transition-colors" />
                                <div onMouseDown={(e) => startDrag(e, region.id, 'resize-end')}
                                    className="absolute right-0 top-0 bottom-0 w-2 cursor-ew-resize hover:bg-white/20 z-30 transition-colors" />

                                <div className="absolute inset-0 flex items-center px-2 pointer-events-none overflow-hidden">
                                    <span className={`text-[10px] font-semibold tracking-[0.3px] whitespace-nowrap truncate ${isSelected ? 'text-white' : 'text-white/70'}`}>
                                        {MODE_LABELS[region.mode] || region.mode}
                                    </span>
                                </div>
                            </div>
                        );
                    })}

                    <div
                        ref={playheadRef}
                        className="absolute top-0 bottom-0 w-[1.5px] bg-white z-40 pointer-events-none"
                        style={{ left: `${(currentTime / duration) * 100}%` }}
                    >
                        <div className="absolute -top-[3px] left-1/2 -translate-x-1/2 w-[7px] h-[7px] bg-white rounded-full" />
                    </div>
                </div>
            </div>
        </div>
    );
});

function formatTime(seconds: number) {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
}

import React from 'react';
import { Upload } from 'lucide-react';
import { Flow } from 'flow-sdk';
import { MediaState } from '../types';

interface Props {
    onSelect: (media: MediaState) => void;
    loading?: boolean;
}

export const VideoUploader: React.FC<Props> = ({ onSelect, loading }) => {
    const handleSelect = async () => {
        try {
            const media = await Flow.media.select({ filter: 'video' });
            if (media && media.type === 'video') {
                const bytes = Uint8Array.from(atob(media.base64), c => c.charCodeAt(0));
                const blob = new Blob([bytes], { type: media.mimeType });
                const file = new File([blob], media.name || 'video.mp4', { type: media.mimeType });
                const dataUrl = URL.createObjectURL(file);

                onSelect({
                    id: media.mediaId,
                    dataUrl,
                    name: media.name || 'video.mp4',
                    type: 'video',
                    file,
                });
            }
        } catch (err) {
            console.error('Failed to select media:', err);
        }
    };

    return (
        <div
            onClick={!loading ? handleSelect : undefined}
            className={`\n                relative group cursor-pointer w-full\n                p-6 sm:p-8 md:p-12 flex flex-col items-center justify-center gap-3\n                bg-[#1a1a1a] transition-all duration-300\n                ${loading ? 'opacity-50 cursor-not-allowed' : 'hover:bg-zinc-800/60'}\n            `}
        >
            <button
                disabled={loading}
                className="mt-2 px-5 py-2 bg-white text-black font-medium rounded-full flex items-center gap-2 hover:bg-zinc-200 whitespace-nowrap text-[13px] sm:text-sm"
            >
                <Upload size={16} />
                Import Video
            </button>
            <div className="text-center">
                <p className="text-[10px] sm:text-xs text-zinc-500 whitespace-nowrap">
                    High motion clips work best.
                </p>
            </div>
        </div>
    );
};

/**
 * Datamosh Engine — Full Timeline Renderer (Optimized)
 *
 * Pipeline:
 * 1. Sort mosh regions by start time
 * 2. Split the timeline into segments (original gaps + moshed regions)
 * 3. For each original segment: FFmpeg copies from source
 * 4. For each moshed segment:
 *    a) FFmpeg re-encodes with -g 99999999 (single GOP) — required for datamosh
 *    b) mediabunny extracts raw encoded packets
 *    c) Packets are manipulated (I-frame removal, repetition, shuffling)
 *    d) VideoDecoder batch-decodes the corrupted stream (NO setInterval)
 *    e) VideoEncoder (HW H.264) + mediabunny muxes directly to MP4
 * 5. FFmpeg concat demuxer joins all segments → final MP4
 * 6. Output matches source resolution and covers the full timeline
 */

import { ffmpegService } from './ffmpegService';
import { fetchFile } from '@ffmpeg/util';
import {
    Input,
    BlobSource as MBBlobSource,
    EncodedPacketSink,
    EncodedVideoPacketSource,
    EncodedPacket,
    Output,
    Mp4OutputFormat,
    BufferTarget,
    MP4,
} from 'mediabunny';
import type { MoshSettings, MoshRegion } from '../types';

const FPS = 30;

export interface MoshResult {
    url: string;
    blob: Blob;
}

// ─── FFmpeg loader ──────────────────────────────────────────────────────

async function ensureFFmpegLoaded(onStatus?: (msg: string) => void) {
    onStatus?.('Loading FFmpeg...');
    await ffmpegService.load((msg) => {
        // Defensive check: ensure msg is a string before calling includes
        const log = typeof msg === 'string' ? msg : String(msg);
        if (!log.includes('built with')) {
            onStatus?.(log);
        }
    });
}

// ─── Get source video metadata ──────────────────────────────────────────

async function getSourceMetadata(file: File): Promise<{
    width: number; height: number; duration: number;
}> {
    const input = new Input({
        source: new MBBlobSource(file),
        formats: [MP4],
    });
    const track = await input.getPrimaryVideoTrack();
    if (!track) throw new Error('No video track found');
    const duration = await track.computeDuration();
    const width = track.codedWidth;
    const height = track.codedHeight;
    input.dispose();
    return { width, height, duration };
}

// ─── Single-region mosh pipeline ────────────────────────────────────────

/** Re-encode a file (or segment) with single-GOP for packet extraction */
async function reencodeSegment(
    inputFile: string,
    outputFile: string,
    startSec?: number,
    durSec?: number,
    scaleToSize?: { w: number; h: number },
): Promise<Uint8Array> {
    const args: string[] = [];
    if (startSec !== undefined && startSec > 0) args.push('-ss', startSec.toFixed(3));
    args.push('-i', inputFile);
    if (durSec !== undefined) args.push('-t', durSec.toFixed(3));
    // Force same resolution for transition clips — critical for packet compatibility
    if (scaleToSize) {
        args.push('-vf', `scale=${scaleToSize.w}:${scaleToSize.h}:force_original_aspect_ratio=decrease,pad=${scaleToSize.w}:${scaleToSize.h}:(ow-iw)/2:(oh-ih)/2`);
    }
    args.push(
        '-vcodec', 'libx264',
        '-g', '99999999',
        '-bf', '0',
        '-flags:v', '+cgop',
        '-pix_fmt', 'yuv420p',
        '-movflags', 'faststart',
        '-crf', '15',
        '-preset', 'ultrafast',
        '-an',
        outputFile,
    );
    await ffmpegService.exec(args);
    const data = await ffmpegService.readFile(outputFile) as Uint8Array;
    await ffmpegService.deleteFile(outputFile);
    return data;
}

/** Extract encoded packets from an MP4 buffer via mediabunny */
interface PacketInfo { chunk: EncodedVideoChunk; isKey: boolean; }

async function extractPacketsFromData(
    mp4Data: Uint8Array,
): Promise<{ packets: PacketInfo[]; config: VideoDecoderConfig }> {
    const blob = new Blob([mp4Data], { type: 'video/mp4' });
    const input = new Input({
        source: new MBBlobSource(blob),
        formats: [MP4],
    });
    const videoTrack = await input.getPrimaryVideoTrack();
    if (!videoTrack) throw new Error('No video track found');
    const config = await videoTrack.getDecoderConfig();
    if (!config) throw new Error('Could not get VideoDecoderConfig');

    const sink = new EncodedPacketSink(videoTrack);
    const packets: PacketInfo[] = [];
    for await (const packet of sink.packets()) {
        const chunk = packet.toEncodedVideoChunk();
        packets.push({ chunk, isKey: chunk.type === 'key' });
    }
    input.dispose();
    return { packets, config };
}

async function moshRegion(
    region: MoshRegion,
    sourceWidth: number,
    sourceHeight: number,
    onStatus?: (msg: string) => void,
): Promise<Uint8Array> {
    const startSec = region.startMs / 1000;
    const durSec = region.durationMs / 1000;

    if (region.mode === 'transition' && region.transitionFile) {
        // ─── TRANSITION MOSH ─────────────────────────────────────
        const dims = { w: sourceWidth, h: sourceHeight };

        onStatus?.('Re-encoding source for transition...');
        const srcData = await reencodeSegment(
            'source.mp4', `trans_src_${region.id}.mp4`, startSec, durSec, dims
        );
        const { packets: srcPackets, config } = await extractPacketsFromData(srcData);

        onStatus?.('Re-encoding transition clip (matching resolution)...');
        const transInputName = `trans_input_${region.id}.mp4`;
        await ffmpegService.writeFile(transInputName, await fetchFile(region.transitionFile));

        let transData: Uint8Array;
        try {
            transData = await reencodeSegment(
                transInputName, `trans_reenc_${region.id}.mp4`, 0, durSec, dims
            );
        } finally {
            await ffmpegService.deleteFile(transInputName).catch(() => {});
        }

        const { packets: transPackets } = await extractPacketsFromData(transData);

        if (transPackets.filter(p => !p.isKey).length === 0) {
            throw new Error('Transition clip produced no delta frames — try a longer clip');
        }

        onStatus?.(`Building transition stream (${srcPackets.length} + ${transPackets.length} packets)...`);
        const moshed = buildTransitionStream(srcPackets, transPackets, region.intensity);

        onStatus?.(`Encoding ${moshed.length} transition packets → MP4...`);
        const targetFrames = Math.ceil(durSec * FPS);
        return decodeAndEncode(moshed, config, sourceWidth, sourceHeight, targetFrames);
    }

    // ─── STANDARD MOSH MODES ─────────────────────────────────
    const dims = { w: sourceWidth, h: sourceHeight };

    onStatus?.(`Re-encoding ${region.mode} region (${durSec.toFixed(1)}s)...`);
    const reencodedData = await reencodeSegment(
        'source.mp4', `mosh_reenc_${region.id}.mp4`, startSec, durSec
    );
    const { packets: srcPackets, config } = await extractPacketsFromData(reencodedData);

    let packets: PacketInfo[];
    if (region.transitionFile) {
        onStatus?.('Re-encoding secondary clip...');
        const secInputName = `sec_input_${region.id}.mp4`;
        await ffmpegService.writeFile(secInputName, await fetchFile(region.transitionFile));
        let secData: Uint8Array;
        try {
            secData = await reencodeSegment(
                secInputName, `sec_reenc_${region.id}.mp4`, 0, durSec, dims
            );
        } finally {
            await ffmpegService.deleteFile(secInputName).catch(() => {});
        }
        const { packets: secPackets } = await extractPacketsFromData(secData);

        const srcKeys = srcPackets.filter(p => p.isKey);
        const secDeltas = secPackets.filter(p => !p.isKey);
        if (secDeltas.length > 0) {
            packets = [...srcKeys, ...secDeltas];
        } else {
            packets = srcPackets; 
        }
    } else {
        packets = srcPackets;
    }

    if (packets.length < 2) throw new Error('Not enough packets');

    onStatus?.(`Applying ${region.mode} effect (${packets.length} packets)...`);
    let moshed: EncodedVideoChunk[];
    switch (region.mode) {
        case 'liquid': moshed = buildLiquidStream(packets, region.intensity); break;
        case 'trail': moshed = buildTrailStream(packets, region.intensity); break;
        case 'bloom': moshed = buildBloomStream(packets, region.intensity); break;
        case 'stutter': moshed = buildStutterStream(packets, region.intensity); break;
        case 'reverse': moshed = buildReverseStream(packets, region.intensity); break;
        case 'pulse': moshed = buildPulseStream(packets, region.intensity); break;
        case 'shatter': moshed = buildShatterStream(packets, region.intensity); break;
        default: moshed = buildLiquidStream(packets, region.intensity);
    }

    onStatus?.(`Encoding ${moshed.length} packets → MP4...`);
    const targetFrames = Math.ceil(durSec * FPS);
    return decodeAndEncode(moshed, config, sourceWidth, sourceHeight, targetFrames);
}

// ─── Packet stream manipulators ─────────────────────────────────────────

function buildLiquidStream(packets: PacketInfo[], intensity: number): EncodedVideoChunk[] {
    const result: EncodedVideoChunk[] = [];
    let foundFirst = false;
    for (const p of packets) {
        if (p.isKey) {
            if (!foundFirst) { result.push(p.chunk); foundFirst = true; }
            continue;
        }
        result.push(p.chunk);
    }
    if (intensity > 60) {
        const repeats = Math.floor((intensity - 60) / 20) + 1;
        const expanded: EncodedVideoChunk[] = [result[0]];
        for (let i = 1; i < result.length; i++) {
            expanded.push(result[i]);
            for (let r = 0; r < repeats; r++) expanded.push(result[i]);
        }
        return expanded;
    }
    return result;
}

function buildTrailStream(packets: PacketInfo[], intensity: number): EncodedVideoChunk[] {
    const result: EncodedVideoChunk[] = [];
    const repeatCount = Math.floor(2 + (intensity / 100) * 6);
    let foundFirst = false;
    for (const p of packets) {
        if (p.isKey && !foundFirst) { result.push(p.chunk); foundFirst = true; continue; }
        if (p.isKey) continue;
        for (let i = 0; i < repeatCount; i++) result.push(p.chunk);
    }
    return result;
}

function buildBloomStream(packets: PacketInfo[], intensity: number): EncodedVideoChunk[] {
    const result: EncodedVideoChunk[] = [];
    let foundFirst = false;
    const deltas: EncodedVideoChunk[] = [];
    for (const p of packets) {
        if (p.isKey && !foundFirst) { result.push(p.chunk); foundFirst = true; continue; }
        if (p.isKey) continue;
        deltas.push(p.chunk);
    }
    const segSize = Math.max(3, Math.floor(24 * (1 - intensity / 100)));
    const segments: EncodedVideoChunk[][] = [];
    for (let i = 0; i < deltas.length; i += segSize) segments.push(deltas.slice(i, i + segSize));
    for (let i = segments.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [segments[i], segments[j]] = [segments[j], segments[i]];
    }
    for (const seg of segments) {
        result.push(...(Math.random() > 0.5 ? seg.slice().reverse() : seg));
    }
    return result;
}

function buildStutterStream(packets: PacketInfo[], intensity: number): EncodedVideoChunk[] {
    const result: EncodedVideoChunk[] = [];
    let foundFirst = false;
    const deltas: EncodedVideoChunk[] = [];
    for (const p of packets) {
        if (p.isKey && !foundFirst) { result.push(p.chunk); foundFirst = true; continue; }
        if (p.isKey) continue;
        deltas.push(p.chunk);
    }
    const loopSize = Math.max(2, Math.floor(8 * (1 - intensity / 100)));
    const skipChance = 0.1 + (intensity / 100) * 0.35;
    let i = 0;
    while (i < deltas.length) {
        if (Math.random() < skipChance) { i += Math.floor(Math.random() * 12) + 2; continue; }
        const end = Math.min(i + loopSize, deltas.length);
        const loops = Math.floor(Math.random() * 4) + 2;
        for (let l = 0; l < loops; l++) for (let j = i; j < end; j++) result.push(deltas[j]);
        i = end;
    }
    return result;
}

function buildReverseStream(packets: PacketInfo[], intensity: number): EncodedVideoChunk[] {
    const result: EncodedVideoChunk[] = [];
    let foundFirst = false;
    const deltas: EncodedVideoChunk[] = [];
    for (const p of packets) {
        if (p.isKey && !foundFirst) { result.push(p.chunk); foundFirst = true; continue; }
        if (p.isKey) continue;
        deltas.push(p.chunk);
    }
    const segSize = Math.max(2, Math.floor(30 * (1 - intensity / 100)));
    const segments: EncodedVideoChunk[][] = [];
    for (let i = 0; i < deltas.length; i += segSize) {
        segments.push(deltas.slice(i, i + segSize));
    }
    segments.reverse();
    for (const seg of segments) {
        result.push(...seg.reverse());
    }
    return result;
}

function buildPulseStream(packets: PacketInfo[], intensity: number): EncodedVideoChunk[] {
    const result: EncodedVideoChunk[] = [];
    let keyframe: EncodedVideoChunk | null = null;
    const deltas: EncodedVideoChunk[] = [];
    for (const p of packets) {
        if (p.isKey && !keyframe) { keyframe = p.chunk; continue; }
        if (p.isKey) continue;
        deltas.push(p.chunk);
    }
    if (!keyframe) return [];
    const interval = Math.max(3, Math.floor(30 * (1 - intensity / 100)));
    result.push(keyframe);
    for (let i = 0; i < deltas.length; i++) {
        if (i > 0 && i % interval === 0) {
            result.push(keyframe); 
        }
        result.push(deltas[i]);
    }
    return result;
}

function buildShatterStream(packets: PacketInfo[], intensity: number): EncodedVideoChunk[] {
    const result: EncodedVideoChunk[] = [];
    let foundFirst = false;
    const deltas: EncodedVideoChunk[] = [];
    for (const p of packets) {
        if (p.isKey && !foundFirst) { result.push(p.chunk); foundFirst = true; continue; }
        if (p.isKey) continue;
        deltas.push(p.chunk);
    }
    const randomChance = 0.2 + (intensity / 100) * 0.7; 
    for (let i = 0; i < deltas.length; i++) {
        if (Math.random() < randomChance) {
            const randIdx = Math.floor(Math.random() * deltas.length);
            result.push(deltas[randIdx]);
        } else {
            result.push(deltas[i]);
        }
    }
    return result;
}

function buildTransitionStream(
    srcPackets: PacketInfo[],
    transPackets: PacketInfo[],
    intensity: number,
): EncodedVideoChunk[] {
    const result: EncodedVideoChunk[] = [];
    const srcKeyframes = srcPackets.filter(p => p.isKey);
    if (srcKeyframes.length === 0) throw new Error('No keyframe in source');
    const transDeltas = transPackets.filter(p => !p.isKey);
    if (transDeltas.length === 0) throw new Error('No delta frames in transition clip');
    result.push(srcKeyframes[0].chunk);
    const resetInterval = intensity >= 90
        ? Infinity
        : Math.max(3, Math.floor(transDeltas.length * (1 - intensity / 100)));
    for (let i = 0; i < transDeltas.length; i++) {
        if (resetInterval !== Infinity && i > 0 && i % resetInterval === 0) {
            result.push(srcKeyframes[0].chunk);
        }
        result.push(transDeltas[i].chunk);
    }
    return result;
}

async function decodeAndEncode(
    chunks: EncodedVideoChunk[],
    config: VideoDecoderConfig,
    width: number,
    height: number,
    targetFrames: number,
): Promise<Uint8Array> {
    const frames: VideoFrame[] = [];
    const decoder = new VideoDecoder({
        error: (e) => console.debug('Decoder (expected mosh):', e.message),
        output: (frame) => {
            if (frames.length < targetFrames) {
                frames.push(frame);
            } else {
                frame.close();
            }
        },
    });
    decoder.configure(config);
    for (const chunk of chunks) {
        try { decoder.decode(chunk); } catch (e) {}
    }
    await decoder.flush().catch(() => {});
    if (decoder.state !== 'closed') decoder.close();
    if (frames.length === 0) {
        throw new Error('Decoder produced no frames');
    }
    while (frames.length < targetFrames) {
        const lastFrame = frames[frames.length - 1];
        frames.push(new VideoFrame(lastFrame, { timestamp: lastFrame.timestamp! }));
    }
    const target = new BufferTarget();
    const output = new Output({
        format: new Mp4OutputFormat({ fastStart: 'in-memory' }),
        target,
    });
    const videoSource = new EncodedVideoPacketSource('avc');
    output.addVideoTrack(videoSource);
    await output.start();
    const encoderDone = new Promise<void>((resolve, reject) => {
        const encoder = new VideoEncoder({
            output: async (chunk, meta) => {
                try {
                    await videoSource.add(
                        EncodedPacket.fromEncodedChunk(chunk),
                        meta ?? undefined,
                    );
                } catch (e) {
                    console.debug('Muxer add error (non-fatal):', e);
                }
            },
            error: reject,
        });
        encoder.configure({
            codec: 'avc1.4d0034', 
            width,
            height,
            bitrate: 8_000_000,
            framerate: FPS,
        });
        const frameDuration = 1_000_000 / FPS; 
        for (let i = 0; i < frames.length; i++) {
            const frame = frames[i];
            const retimedFrame = new VideoFrame(frame, {
                timestamp: i * frameDuration,
                duration: frameDuration,
            });
            frame.close();
            encoder.encode(retimedFrame, { keyFrame: i === 0 });
            retimedFrame.close();
        }
        encoder.flush().then(() => {
            encoder.close();
            resolve();
        }).catch(reject);
    });
    await encoderDone;
    await output.finalize();
    return new Uint8Array(target.buffer);
}

function snapToFrame(sec: number): number {
    return Math.round(sec * FPS) / FPS;
}

function framesToCount(startSec: number, endSec: number): number {
    return Math.round((endSec - startSec) * FPS);
}

interface Segment {
    type: 'original' | 'moshed';
    startSec: number;
    endSec: number;
    frames: number;
    region?: MoshRegion;
    filename: string;
}

export type AudioMode = 'none' | 'preserve' | 'glitch';

export async function renderFullTimeline(
    file: File,
    regions: MoshRegion[],
    onProgress?: (progress: number) => void,
    onStatus?: (msg: string) => void,
    audioMode: AudioMode = 'none',
): Promise<MoshResult> {
    await ensureFFmpegLoaded(onStatus);
    onStatus?.('Analyzing source video...');
    const { width, height, duration: srcDuration } = await getSourceMetadata(file);
    const totalMs = srcDuration * 1000;
    onStatus?.('Loading source into FFmpeg...');
    await ffmpegService.writeFile('source.mp4', await fetchFile(file));
    const sorted = [...regions]
        .filter(r => r.durationMs > 0)
        .sort((a, b) => a.startMs - b.startMs);
    const segments: Segment[] = [];
    let segIdx = 0;
    let cursor = 0; 
    for (const region of sorted) {
        const rStart = snapToFrame(Math.max(0, region.startMs / 1000));
        const rEnd = snapToFrame(Math.min(srcDuration, (region.startMs + region.durationMs) / 1000));
        if (rStart > cursor + (1 / FPS)) {
            segments.push({
                type: 'original',
                startSec: cursor,
                endSec: rStart,
                frames: framesToCount(cursor, rStart),
                filename: `seg_${segIdx++}.mp4`,
            });
        }
        segments.push({
            type: 'moshed',
            startSec: rStart,
            endSec: rEnd,
            frames: framesToCount(rStart, rEnd),
            region,
            filename: `seg_${segIdx++}.mp4`,
        });
        cursor = rEnd;
    }
    const snappedEnd = snapToFrame(srcDuration);
    if (cursor < snappedEnd - (1 / FPS)) {
        segments.push({
            type: 'original',
            startSec: cursor,
            endSec: snappedEnd,
            frames: framesToCount(cursor, snappedEnd),
            filename: `seg_${segIdx++}.mp4`,
        });
    }
    const totalSegments = segments.length;
    for (let i = 0; i < segments.length; i++) {
        const seg = segments[i];
        const baseProgress = i / totalSegments;
        onProgress?.(baseProgress);
        if (seg.type === 'original') {
            onStatus?.(`Copying original segment ${i + 1}/${totalSegments} (${seg.frames} frames)...`);
            await ffmpegService.exec([
                '-i', 'source.mp4',
                '-ss', seg.startSec.toFixed(6),
                '-frames:v', String(seg.frames),
                '-c:v', 'libx264',
                '-preset', 'ultrafast',
                '-pix_fmt', 'yuv420p',
                '-r', String(FPS),
                '-video_track_timescale', String(FPS * 3000),
                '-an',
                '-y', seg.filename,
            ]);
        } else {
            const mp4Data = await moshRegion(seg.region!, width, height, onStatus);
            onStatus?.(`Writing moshed segment ${i + 1}/${totalSegments}...`);
            await ffmpegService.writeFile(seg.filename, mp4Data);
        }
        onProgress?.((i + 1) / totalSegments * 0.9);
    }
    onStatus?.('Joining segments into final MP4...');
    onProgress?.(0.9);
    const concatContent = segments.map(s => `file '${s.filename}'`).join('\n');
    await ffmpegService.writeFile('concat.txt',
        new TextEncoder().encode(concatContent));
    await ffmpegService.exec([
        '-f', 'concat', '-safe', '0',
        '-i', 'concat.txt',
        '-c', 'copy',
        '-movflags', 'faststart',
        '-y', 'output_video.mp4',
    ]);
    let finalFile = 'output_video.mp4';
    if (audioMode !== 'none') {
        onStatus?.(audioMode === 'glitch' ? 'Glitching audio...' : 'Muxing audio...');
        onProgress?.(0.95);
        if (audioMode === 'preserve') {
            await ffmpegService.exec([
                '-i', 'output_video.mp4',
                '-i', 'source.mp4',
                '-c:v', 'copy',
                '-c:a', 'aac', '-b:a', '192k',
                '-map', '0:v:0',
                '-map', '1:a:0?',
                '-shortest',
                '-movflags', 'faststart',
                '-y', 'output_final.mp4',
            ]);
            finalFile = 'output_final.mp4';
        } else {
            await ffmpegService.exec([
                '-i', 'output_video.mp4',
                '-i', 'source.mp4',
                '-c:v', 'copy',
                '-map', '0:v:0',
                '-map', '1:a:0?',
                '-af', 'aecho=0.8:0.88:60|120:0.4|0.25,aphaser=type=t:speed=2:decay=0.6,atempo=0.98',
                '-c:a', 'aac', '-b:a', '192k',
                '-shortest',
                '-movflags', 'faststart',
                '-y', 'output_final.mp4',
            ]);
            finalFile = 'output_final.mp4';
        }
    }
    const outputData = await ffmpegService.readFile(finalFile) as Uint8Array;
    const outputBlob = new Blob([outputData.buffer], { type: 'video/mp4' });
    const url = URL.createObjectURL(outputBlob);
    onProgress?.(1);
    onStatus?.('Done!');
    const cleanup = async () => {
        for (const seg of segments) await ffmpegService.deleteFile(seg.filename).catch(() => {});
        await ffmpegService.deleteFile('source.mp4').catch(() => {});
        await ffmpegService.deleteFile('concat.txt').catch(() => {});
        await ffmpegService.deleteFile('output_video.mp4').catch(() => {});
        await ffmpegService.deleteFile('output_final.mp4').catch(() => {});
    };
    cleanup();
    return { url, blob: outputBlob };
}

/**
 * FFmpegService — Manual Worker Management
 * 
 * Bypasses @ffmpeg/ffmpeg and @ffmpeg/util to avoid CORS/atob issues in the 
 * Flow sandboxed iframe. 
 */

interface FFMessage {
  id: number;
  type: string;
  data?: any;
}

class FFmpegService {
  private worker: Worker | null = null;
  private messageId = 0;
  private callbacks = new Map<number, { resolve: (val: any) => void; reject: (err: any) => void }>();
  private logCallback?: (msg: string) => void;
  private progressCallback?: (p: { progress: number }) => void;
  private loaded = false;

  async load(onLog?: (msg: string) => void) {
    if (this.loaded) return;
    this.logCallback = onLog;

    const baseURL = 'https://unpkg.com/@ffmpeg/core@0.12.6/dist/umd';

    onLog?.('Fetching FFmpeg core assets...');

    // 1. Fetch JS core as a Blob URL for importScripts
    const jsRes = await fetch(`${baseURL}/ffmpeg-core.js`);
    const jsBlob = await jsRes.blob();
    const coreURL = URL.createObjectURL(new Blob([jsBlob], { type: 'text/javascript' }));

    // 2. Fetch WASM as an ArrayBuffer to pass directly
    const wasmRes = await fetch(`${baseURL}/ffmpeg-core.wasm`);
    const wasmBinary = await wasmRes.arrayBuffer();

    // 3. Create the classic worker script.
    const workerScript = `
      let ffmpeg;
      const FFMessageType = {
        LOAD: "LOAD", EXEC: "EXEC", WRITE_FILE: "WRITE_FILE", 
        READ_FILE: "READ_FILE", DELETE_FILE: "DELETE_FILE",
        LOG: "LOG", PROGRESS: "PROGRESS", ERROR: "ERROR"
      };

      self.onmessage = async ({ data: { id, type, data } }) => {
        try {
          switch (type) {
            case FFMessageType.LOAD:
              importScripts(data.coreURL);

              ffmpeg = await self.createFFmpegCore({
                wasmBinary: data.wasmBinary,
                onRuntimeInitialized: () => {},
              });

              // Ensure log is always a string before sending
              ffmpeg.setLogger((log) => {
                const message = typeof log === 'string' ? log : (log.message || '');
                self.postMessage({ type: FFMessageType.LOG, data: message });
              });

              ffmpeg.setProgress((p) => {
                const progress = typeof p === 'object' ? p.progress : p;
                self.postMessage({ type: FFMessageType.PROGRESS, data: progress });
              });

              self.postMessage({ id, type, data: true });
              break;

            case FFMessageType.EXEC:
              const ret = ffmpeg.exec(...data.args);
              self.postMessage({ id, type, data: ret });
              break;

            case FFMessageType.WRITE_FILE:
              ffmpeg.FS.writeFile(data.path, data.data);
              self.postMessage({ id, type, data: true });
              break;

            case FFMessageType.READ_FILE:
              const fileData = ffmpeg.FS.readFile(data.path);
              const buffer = fileData.buffer.slice(0);
              self.postMessage({ id, type, data: new Uint8Array(buffer) }, [buffer]);
              break;

            case FFMessageType.DELETE_FILE:
              ffmpeg.FS.unlink(data.path);
              self.postMessage({ id, type, data: true });
              break;
          }
        } catch (err) {
          self.postMessage({ id, type: FFMessageType.ERROR, data: err.toString() });
        }
      };
    `;

    const workerBlob = new Blob([workerScript], { type: 'text/javascript' });
    this.worker = new Worker(URL.createObjectURL(workerBlob));

    this.worker.onmessage = (e: MessageEvent) => {
      const { id, type, data } = e.data;
      if (type === 'LOG') {
        // Double-check normalization to string
        const msgStr = typeof data === 'string' ? data : JSON.stringify(data);
        this.logCallback?.(msgStr);
        return;
      }
      if (type === 'PROGRESS') {
        this.progressCallback?.({ progress: data });
        return;
      }
      const cb = this.callbacks.get(id);
      if (!cb) return;
      if (type === 'ERROR') {
        cb.reject(new Error(data));
      } else {
        cb.resolve(data);
      }
      this.callbacks.delete(id);
    };

    await this.send('LOAD', { coreURL, wasmBinary }, [wasmBinary]);
    this.loaded = true;
  }

  private async send(type: string, data?: any, transfer: Transferable[] = []): Promise<any> {
    if (!this.worker) throw new Error('Worker not initialized');
    const id = this.messageId++;
    return new Promise((resolve, reject) => {
      this.callbacks.set(id, { resolve, reject });
      this.worker!.postMessage({ id, type, data }, transfer);
    });
  }

  async exec(args: string[]) {
    return this.send('EXEC', { args });
  }

  async writeFile(path: string, data: Uint8Array) {
    return this.send('WRITE_FILE', { path, data });
  }

  async readFile(path: string): Promise<Uint8Array> {
    return this.send('READ_FILE', { path });
  }

  async deleteFile(path: string) {
    return this.send('DELETE_FILE', { path });
  }

  onProgress(cb: (p: { progress: number }) => void) {
    this.progressCallback = cb;
  }
}

export const ffmpegService = new FFmpegService();

export type MoshMode = 'liquid' | 'bloom' | 'stutter' | 'transition' | 'reverse' | 'pulse';

export interface MoshSettings {
    mode: MoshMode;
    intensity: number;
    fps: number;
    preserveAudio: boolean;
}

export interface MoshRegion {
    id: string;
    mode: MoshMode;
    intensity: number;
    startMs: number;
    durationMs: number;
    // Transition mode: second clip whose motion vectors warp the source pixels
    transitionFile?: File;
    transitionName?: string;
}

export interface MediaState {
    id: string;
    dataUrl: string;
    name: string;
    type: 'video';
    file?: File;
    duration?: number; // seconds
}
